def parse_csv(text):
    rows = []
    row = []
    field = []
    i = 0
    n = len(text)

    if n == 0:
        return []

    while True:
        # 解析一个字段
        if i < n and text[i] == '"':
            # 带引号字段
            i += 1
            while True:
                if i >= n:
                    raise ValueError("unclosed quoted field")
                ch = text[i]
                if ch == '"':
                    if i + 1 < n and text[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    field.append(ch)
                    i += 1
            # 结束引号后只能是逗号、LF 或 EOF
            if i < n and text[i] not in (',', '\n'):
                raise ValueError("unexpected character after closing quote")
        else:
            # 普通字段
            while i < n and text[i] not in (',', '\n'):
                if text[i] == '"':
                    raise ValueError("quote in unquoted field")
                field.append(text[i])
                i += 1

        row.append(''.join(field))
        field = []

        if i >= n:
            rows.append(row)
            break
        if text[i] == ',':
            i += 1
            if i >= n:
                # 尾逗号产生空字段
                row.append('')
                rows.append(row)
                break
            continue
        # text[i] == '\n'
        i += 1
        rows.append(row)
        row = []
        if i >= n:
            # 最后一个 LF 只终止当前行
            break

    return rows

