def _decode_token(token):
    result = []
    i = 0
    n = len(token)
    while i < n:
        ch = token[i]
        if ch == "~":
            if i + 1 >= n:
                raise ValueError("invalid escape: trailing '~'")
            nxt = token[i + 1]
            if nxt == "0":
                result.append("~")
            elif nxt == "1":
                result.append("/")
            else:
                raise ValueError("invalid escape: '~%s'" % nxt)
            i += 2
        else:
            result.append(ch)
            i += 1
    return "".join(result)


def _parse_index(token):
    if token == "0":
        return 0
    if not token:
        raise ValueError("invalid list index: empty")
    first = token[0]
    if not ("1" <= first <= "9"):
        raise ValueError("invalid list index: %r" % token)
    for ch in token[1:]:
        if not ("0" <= ch <= "9"):
            raise ValueError("invalid list index: %r" % token)
    return int(token)


def resolve_pointer(document, pointer):
    if not isinstance(pointer, str):
        raise ValueError("pointer must be a string")
    if pointer == "":
        return document
    if not pointer.startswith("/"):
        raise ValueError("non-empty pointer must start with '/'")
    value = document
    for raw_token in pointer.split("/")[1:]:
        token = _decode_token(raw_token)
        if isinstance(value, list):
            index = _parse_index(token)
            if index >= len(value):
                raise ValueError("list index out of range: %d" % index)
            value = value[index]
        elif isinstance(value, dict):
            if token not in value:
                raise ValueError("missing key: %r" % token)
            value = value[token]
        else:
            raise ValueError("cannot traverse scalar value")
    return value

def dependency_layers(dependencies):
    # Build graph without mutating the input.
    graph = {}
    for task, prereqs in dependencies.items():
        graph.setdefault(task, set())
        for p in prereqs:
            graph.setdefault(p, set())
            graph[task].add(p)

    # Kahn's algorithm, layer by layer.
    remaining = {node: set(prereqs) for node, prereqs in graph.items()}
    result = []
    while remaining:
        ready = sorted(node for node, prereqs in remaining.items() if not prereqs)
        if not ready:
            raise ValueError("cycle detected in dependencies")
        result.append(ready)
        ready_set = set(ready)
        for node in ready:
            del remaining[node]
        for prereqs in remaining.values():
            prereqs.difference_update(ready_set)

    return result

