def apply_transfers(accounts, transfers):
    if not isinstance(accounts, dict):
        raise ValueError("accounts must be a dict")
    if not isinstance(transfers, (list, tuple)):
        raise ValueError("transfers must be a list")

    def is_valid_balance(value):
        return isinstance(value, int) and not isinstance(value, bool) and value >= 0

    def is_valid_amount(value):
        return isinstance(value, int) and not isinstance(value, bool) and value > 0

    for name, balance in accounts.items():
        if not isinstance(name, str):
            raise ValueError("account names must be strings")
        if not is_valid_balance(balance):
            raise ValueError("balances must be non-negative ints")

    result = accounts.copy()

    for transfer in transfers:
        if not isinstance(transfer, (list, tuple)) or len(transfer) != 3:
            raise ValueError("each transfer must be [from, to, amount]")
        sender, receiver, amount = transfer
        if not isinstance(sender, str) or not isinstance(receiver, str):
            raise ValueError("transfer accounts must be strings")
        if not is_valid_amount(amount):
            raise ValueError("amount must be a strictly positive int")
        if sender not in result or receiver not in result:
            raise ValueError("unknown account")
        if result[sender] < amount:
            raise ValueError("insufficient balance")
        result[sender] -= amount
        result[receiver] += amount

    return result

