def merge_ranges(ranges):
    """Merge overlapping or adjacent half-open integer intervals.

    Each interval is [start, end). Empty intervals (start == end) are ignored.
    Raises ValueError for malformed intervals or non-integer endpoints
    (bool is not accepted as an integer). The input is not modified.
    """
    normalized = []
    for interval in ranges:
        try:
            length = len(interval)
        except TypeError:
            raise ValueError("each interval must be a sequence of length 2")
        if length != 2:
            raise ValueError("each interval must have exactly 2 endpoints")
        start, end = interval[0], interval[1]
        if isinstance(start, bool) or not isinstance(start, int):
            raise ValueError("interval endpoints must be integers")
        if isinstance(end, bool) or not isinstance(end, int):
            raise ValueError("interval endpoints must be integers")
        if start > end:
            raise ValueError("interval start must not exceed end")
        if start == end:
            continue
        normalized.append((start, end))

    normalized.sort()

    merged = []
    for start, end in normalized:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged

