def window_admit(events, limit, window):
    """Return per-event admission decisions under a sliding window limit.

    events: non-decreasing list of non-negative integers (timestamps).
    limit: positive integer, max accepted events within the window.
    window: positive integer, window size.

    For each event t in order: first drop accepted events with time <= t - window,
    then accept t if fewer than limit accepted events remain, else reject.
    """
    if isinstance(events, bool) or not isinstance(events, (list, tuple)):
        raise ValueError("events must be a list of non-negative integers")
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError("limit must be a positive integer")
    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError("window must be a positive integer")

    # Validate all events up front, including those not yet processed.
    prev = None
    for t in events:
        if isinstance(t, bool) or not isinstance(t, int):
            raise ValueError("events must contain only integers")
        if t < 0:
            raise ValueError("events must be non-negative")
        if prev is not None and t < prev:
            raise ValueError("events must be non-decreasing")
        prev = t

    accepted = []  # list of accepted timestamps, non-decreasing
    head = 0       # index of first still-relevant accepted event
    result = []
    for t in events:
        threshold = t - window
        while head < len(accepted) and accepted[head] <= threshold:
            head += 1
        if len(accepted) - head < limit:
            accepted.append(t)
            result.append(True)
        else:
            result.append(False)
    return result

